## Building a Custom Iterator

### Fibonacci Iterator
```xiom
pub type FibIter = {
  current: Int;
  next: Int;
  count: Int;
  max_count: Int;
}

impl Iterator for FibIter {
  type Item = Int;

  fn next(self: &mut FibIter) -> Option[Int] {
    if self.count >= self.max_count { return None(); }
    let value = self.current;
    let new_next = self.current + self.next;
    self.current = self.next;
    self.next = new_next;
    self.count = self.count + 1;
    return Some(value);
  }
}
```

### Prime Number Iterator
```xiom
pub type PrimeIter = {
  current: Int;
}

impl Iterator for PrimeIter {
  type Item = Int;

  fn next(self: &mut PrimeIter) -> Option[Int] {
    var n = self.current + 1;
    while !is_prime(n) { n = n + 1; }
    self.current = n;
    return Some(n);
  }
}
```

### Infinite Iterator
```xiom
pub type Counter = { value: Int; }

impl Iterator for Counter {
  type Item = Int;

  fn next(self: &mut Counter) -> Option[Int] {
    let v = self.value;
    self.value = self.value + 1;
    return Some(v);  // Never returns None — infinite!
  }
}
```

### File Line Iterator
```xiom
pub type LineIter = { file: File; }

impl Iterator for LineIter {
  type Item = Str;

  fn next(self: &mut LineIter) -> Option[Str] {
    return self.file.read_line();  // Returns None at EOF
  }
}
```

