pub type CollatzIter = {
  current: Int;
  done: Bool;
}

impl Iterator for CollatzIter {
  type Item = Int;

  fn next(self: &mut CollatzIter) -> Option[Int] {
    if self.done { return None(); }
    let value = self.current;
    if self.current == 1 {
      self.done = true;
    } else if self.current % 2 == 0 {
      self.current = self.current / 2;
    } else {
      self.current = 3 * self.current + 1;
    }
    return Some(value);
  }
}

fn main() -> Int {
  let mut iter = CollatzIter{ current: 6, done: false };
  var steps = 0;
  while let Some(n) = iter.next() {
    steps = steps + 1;
  }
  return steps;
}
